        self.assertNotIn("better", payload["neutral"])
        self.assertNotIn("worse", payload["neutral"])
        self.assertIn("+30 pts", payload["points"])
        self.assertIn("better", payload["points"])
        self.assertEqual(payload["missing"], "")

