        self.assertEqual((model_b["reasoning_tokens"], model_b["reasoning_output_tokens"]),
                         (3, 6))
        self.assertEqual(model_b["reasoning_executions"], 1)
        self.assertEqual({item["day"] for item in row["_model_daily"]},
                         {"2026-01-31", "2026-02-01"})

